/**
 * Fixed phrases (docs/legal/textos/07 section E). Not generated by the model: they are loaded into the agent as
 * literal text and used by the engine for the hard cut. Version legal-v1.2 (D13: Santa stays in character with the child; AI disclosure goes to the adult). es-ES variants approved in D11; es-ES falls back
 * to es-419 where the file lists no variant. en-GB ("Father Christmas") has no agent yet: GB buyers get the en block.
 */
import type { Language } from "../types";

export type PhraseId = "E-01" | "E-02" | "E-03" | "D-01" | "D-02" | "D-03" | "D-03b" | "D-04" | "D-05" | "D-06" | "D-07" | "D-08" | "D-09";

type Variants = Partial<Record<Language | "en-GB", string>> & { "es-419": string; en: string };

export const PHRASES: Record<PhraseId, Variants> = {
  // D13: with the child the character is the character. No "computer", "AI" or "robot" about itself.
  "E-01": {
    "es-419": "¡Claro que sí! Soy Santa, y te estoy llamando desde el Polo Norte. ¡Jo, jo, jo!",
    "es-ES": "¡Claro que sí! Soy Papá Noel, y te estoy llamando desde el Polo Norte. ¡Jo, jo, jo!",
    en: "Of course I am! I'm Santa, calling you all the way from the North Pole. Ho, ho, ho!",
    "en-GB": "Of course I am! I'm Father Christmas, calling you all the way from the North Pole. Ho, ho, ho!",
  },
  "E-02": {
    "es-419": "¡Jo, jo, jo! ¡Soy Santa! Los robots son los que ayudan en mi taller a envolver regalos.",
    "es-ES": "¡Jo, jo, jo! ¡Soy Papá Noel! Los robots son los que ayudan en mi taller a envolver regalos.",
    en: "Ho, ho, ho! I'm Santa! The robots are the ones who help wrap presents in my workshop.",
    "en-GB": "Ho, ho, ho! I'm Father Christmas! The robots are the ones who help wrap presents in my workshop.",
  },
  "E-03": {
    "es-419": "¡Jo, jo, jo! Pues aquí estoy, hablando contigo desde el Polo Norte.",
    en: "Ho, ho, ho! Well, here I am, talking with you from the North Pole.",
  },
  "D-01": {
    "es-419": "Eso guárdalo para tu familia. Mejor cuéntame, ¿qué te gusta hacer en Navidad?",
    "es-ES": "Eso guárdaselo a tu familia. Mejor cuéntame, ¿qué te gusta hacer en Navidad?",
    en: "Keep that for your family. Tell me instead, what do you like to do at Christmas?",
  },
  "D-02": {
    "es-419": "Ha sido muy bonito hablar contigo, {{NOMBRE_NIÑO}}. ¡Hasta pronto!",
    en: "It was lovely talking with you, {{NOMBRE_NIÑO}}. Goodbye!",
  },
  "D-03": {
    "es-419": "Hola. Soy la llamada de Santa que pidió para {{NOMBRE_NIÑO}}. ¿Quiere que terminemos o que continúe con el niño?",
    "es-ES": "Hola. Soy la llamada de Papá Noel que ha pedido para {{NOMBRE_NIÑO}}. ¿Quiere que terminemos o que continúe con el niño?",
    en: "Hello. This is the Santa call you ordered for {{NOMBRE_NIÑO}}. Would you like me to end it or continue with your child?",
    "en-GB": "Hello. This is the Father Christmas call you ordered for {{NOMBRE_NIÑO}}. Would you like me to end it or continue with your child?",
  },
  // D13: full AI disclosure to an adult who asks. Names "Lumen Labs" literally (file 07, D-03b), not {{MARCA}}.
  "D-03b": {
    "es-419": "Es una llamada automatizada con voz de inteligencia artificial de Lumen Labs, que pidió la familia de {{NOMBRE_NIÑO}}. ¿Quiere que terminemos o que continúe con el niño?",
    "es-ES": "Es una llamada automatizada con voz de inteligencia artificial de Lumen Labs, que ha pedido la familia de {{NOMBRE_NIÑO}}. ¿Quiere que terminemos o que continúe con el niño?",
    en: "This is an automated call with an artificial intelligence voice from Lumen Labs, requested by {{NOMBRE_NIÑO}}'s family. Would you like me to end it or continue with your child?",
  },
  "D-04": {
    "es-419": "Entendido. Terminamos aquí y no volveremos a llamar a este número. Que tengan un buen día.",
    en: "Understood. We will end here and will not call this number again. Have a good day.",
  },
  "D-05": {
    "es-419": "Gracias por contármelo. Lo que sientes es importante: cuéntaselo ahora mismo a un adulto de confianza, como mamá, papá o alguien de tu familia. Si necesitas ayuda urgente, que un adulto llame al número de emergencias. Adiós.",
    en: "Thank you for telling me. What you feel is important: tell a trusted adult right now, like mom, dad or someone in your family. If you need urgent help, ask an adult to call emergency services. Goodbye.",
  },
  "D-06": {
    "es-419": "Disculpe la molestia. Alguien pidió esta llamada para un niño; si usted no la esperaba, terminamos aquí y no volveremos a llamar a este número.",
    "es-ES": "Disculpe la molestia. Alguien ha pedido esta llamada para un niño; si usted no la esperaba, terminamos aquí y no volveremos a llamar a este número.",
    en: "Sorry to bother you. Someone requested this call for a child; if you were not expecting it, we will end here and will not call this number again.",
  },
  // D11 (legal-v1.1): false-positive fixes. Same text in es-419 and es-ES.
  "D-07": {
    "es-419": "Si algo te duele, díselo ahora mismo a un adulto de tu familia.",
    en: "If something hurts, tell a grown-up in your family right now.",
  },
  "D-08": {
    "es-419": "Esta llamada mágica es especial, solo de hoy. ¡Cuéntale a tu familia todo lo que hablamos!",
    en: "This magic call is special, just for today. Tell your family everything we talked about!",
  },
  "D-09": {
    "es-419": "En la noche de Navidad mis renos y yo viajamos por todo el mundo. ¡Es una noche muy ocupada!",
    en: "On Christmas night my reindeer and I travel all around the world. It's a very busy night!",
  },
};

export function phrase(id: PhraseId, language: Language, variant?: "en-GB"): string {
  const v = PHRASES[id];
  if (variant === "en-GB" && v["en-GB"]) return v["en-GB"];
  return v[language] ?? (language === "es-ES" ? v["es-419"] : v.en);
}
